void main() => runApp(const RentFlowApp());

class RentFlowApp extends StatelessWidget {
  const RentFlowApp({super.key});
  @override
  Widget build(BuildContext context) => MaterialApp(
    debugShowCheckedModeBanner: false,
    title: 'RentFlow',
    theme: ThemeData(useMaterial3: true, scaffoldBackgroundColor: const Color(0xFFF8FFFC), colorScheme: ColorScheme.fromSeed(seedColor: teal), fontFamily: 'sans'),
    home: const AppShell(),
  );
}

class AppShell extends StatefulWidget { const AppShell({super.key}); @override State<AppShell> createState()=>_AppShellState(); }
class _AppShellState extends State<AppShell> {
  int tab=0; final data=Store(); bool loading=true;
  @override void initState(){super.initState(); _load();}
  Future<void> _load() async {await data.load(); if(mounted)setState(()=>loading=false);}
  void refresh()=>setState((){});
  @override Widget build(BuildContext context){
    if(loading) return const Splash();
    final pages=[Home(data:data,onChanged:refresh), ItemsPage(data:data,onChanged:refresh), CustomersPage(data:data,onChanged:refresh), ReportsPage(data:data)];
    return Scaffold(body: pages[tab], bottomNavigationBar: NavigationBar(selectedIndex:tab,onDestinationSelected:(i)=>setState(()=>tab=i),destinations:const[
      NavigationDestination(icon:Icon(Icons.home_outlined),selectedIcon:Icon(Icons.home),label:'Home'),
      NavigationDestination(icon:Icon(Icons.inventory_2_outlined),selectedIcon:Icon(Icons.inventory_2),label:'Items'),
      NavigationDestination(icon:Icon(Icons.groups_outlined),selectedIcon:Icon(Icons.groups),label:'Customers'),
      NavigationDestination(icon:Icon(Icons.bar_chart_outlined),selectedIcon:Icon(Icons.bar_chart),label:'Reports'),
    ]));
  }
}
class Splash extends StatelessWidget {const Splash({super.key}); @override Widget build(BuildContext c)=>Scaffold(body:Center(child:Column(mainAxisSize:MainAxisSize.min,children:[Container(width:92,height:92,decoration:BoxDecoration(color:teal,borderRadius:BorderRadius.circular(28)),child:const Icon(Icons.swap_horiz_rounded,color:Colors.white,size:58)),const SizedBox(height:18),const Text('RentFlow',style:TextStyle(fontSize:38,fontWeight:FontWeight.w800)),const Text('By PaliaAPK HUB',style:TextStyle(color:teal,fontWeight:FontWeight.w700)),const SizedBox(height:8),const Text('Developer by ShanPalia',style:TextStyle(color:Colors.black54))])));}

class Store {
  List<Map<String,dynamic>> items=[]; List<Map<String,dynamic>> customers=[]; List<Map<String,dynamic>> rentals=[]; List<Map<String,dynamic>> invoices=[];
  late SharedPreferences p;
  Future<void> load() async {p=await SharedPreferences.getInstance(); items=_read('items');customers=_read('customers');rentals=_read('rentals');invoices=_read('invoices');}
  List<Map<String,dynamic>> _read(String k){final s=p.getString(k);if(s==null)return[];return List<Map<String,dynamic>>.from((jsonDecode(s) as List).map((e)=>Map<String,dynamic>.from(e)));}
  Future<void> save() async {for(final e in {'items':items,'customers':customers,'rentals':rentals,'invoices':invoices}.entries){await p.setString(e.key,jsonEncode(e.value));}}
  String id()=>DateTime.now().microsecondsSinceEpoch.toString();
}

