    return SafeArea(child:ListView(padding:const EdgeInsets.fromLTRB(18,16,18,24),children:[
      Row(children:[Container(width:48,height:48,decoration:BoxDecoration(color:teal,borderRadius:BorderRadius.circular(14)),child:const Icon(Icons.swap_horiz,color:Colors.white,size:30)),const SizedBox(width:10),const Expanded(child:Text('RentFlow',style:TextStyle(fontSize:27,fontWeight:FontWeight.w800))),IconButton(onPressed:()=>_business(context),icon:const Icon(Icons.settings_outlined))]),
      const SizedBox(height:12), Container(padding:const EdgeInsets.all(18),decoration:BoxDecoration(color:mint,borderRadius:BorderRadius.circular(20)),child:const Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text('Good Morning,',style:TextStyle(color:Colors.black54,fontSize:15)),SizedBox(height:2),Text('Shop Owner',style:TextStyle(fontSize:27,fontWeight:FontWeight.w800)),Text('Manage your rental business easily',style:TextStyle(color:Colors.black54))])),
      const SizedBox(height:16),GridView.count(crossAxisCount:2,shrinkWrap:true,physics:const NeverScrollableScrollPhysics(),crossAxisSpacing:10,mainAxisSpacing:10,childAspectRatio:1.8,children:[_stat('Total Items','$total',Icons.inventory_2),_stat('Available','${total-issued}',Icons.check_circle),_stat('Issued','$issued',Icons.north_east),_stat('Items Due','${data.rentals.where((e)=>e['status']=='issued').length}',Icons.schedule)]),
      const SizedBox(height:14),FilledButton.icon(style:FilledButton.styleFrom(minimumSize:const Size.fromHeight(58),backgroundColor:teal,shape:RoundedRectangleBorder(borderRadius:BorderRadius.circular(18))),onPressed:()=>_rental(context),icon:const Icon(Icons.add_circle_outline),label:const Text('New Rental',style:TextStyle(fontSize:20,fontWeight:FontWeight.w700))),
      const SizedBox(height:12),Row(children:[Expanded(child:_action(context,'Add Item',Icons.inventory_2_outlined,()=>_addItem(context))),Expanded(child:_action(context,'New Customer',Icons.person_add_alt_1,()=>_addCustomer(context))),Expanded(child:_action(context,'Invoice',Icons.receipt_long,()=>_invoiceList(context))),Expanded(child:_action(context,'Receive',Icons.undo,()=>_receive(context)))]),
