      if(data.rentals.isEmpty) const Padding(padding:EdgeInsets.all(30),child:Center(child:Text('No rentals yet'))),
      const SizedBox(height:8),Container(padding:const EdgeInsets.all(16),decoration:BoxDecoration(color:const Color(0xFFFFF0F1),borderRadius:BorderRadius.circular(18)),child:Row(children:[const Icon(Icons.account_balance_wallet_outlined,color:Colors.red),const SizedBox(width:12),Expanded(child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[const Text("Today's Rental Amount",style:TextStyle(fontWeight:FontWeight.w700)),Text('₹${due.toStringAsFixed(0)}',style:const TextStyle(fontSize:23,fontWeight:FontWeight.w800))]))]))
