  Widget _stat(String a,String b,IconData i)=>Container(padding:const EdgeInsets.all(14),decoration:BoxDecoration(color:Colors.white,borderRadius:BorderRadius.circular(16),boxShadow:[BoxShadow(color:Colors.black.withOpacity(.05),blurRadius:10)]),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Icon(i,color:teal),const Spacer(),Text(a,style:const TextStyle(color:Colors.black54)),Text(b,style:const TextStyle(fontSize:23,fontWeight:FontWeight.w800))]));
