  Future<void> _addItem(BuildContext c)async{final n=TextEditingController(),cat=TextEditingController(),q=TextEditingController(text:'1'),rate=TextEditingController();String type='Per Day';final ok=await showDialog<bool>(context:c,builder:(_)=>StatefulBuilder(builder:(c,set)=>AlertDialog(title:const Text('Add Item'),content:SingleChildScrollView(child:Column(children:[_field(n,'Item Name'),_field(cat,'Category'),_field(q,'Total Quantity',number:true),_field(rate,'Rent Price',number:true),DropdownButtonFormField(value:type,items:['Per Day','Per Hour','Per Event'].map((x)=>DropdownMenuItem(value:x,child:Text(x))).toList(),onChanged:(v)=>set(()=>type=v! ),decoration:const InputDecoration(labelText:'Rent Type'))])),actions:[TextButton(onPressed:()=>Navigator.pop(c,false),child:const Text('Cancel')),FilledButton(onPressed:()=>Navigator.pop(c,true),child:const Text('Save'))])));if(ok==true&&n.text.trim().isNotEmpty){data.items.add({'id':data.id(),'name':n.text.trim(),'category':cat.text.trim(),'qty':int.tryParse(q.text)??0,'available':int.tryParse(q.text)??0,'rate':double.tryParse(rate.text)??0,'type':type});await data.save();onChanged();}}
