  Future<void> _rental(BuildContext c)async{if(data.customers.isEmpty||data.items.isEmpty){ScaffoldMessenger.of(c).showSnackBar(const SnackBar(content:Text('Please add at least one customer and one item first.')));return;}String customer=data.customers.first['name'],item=data.items.first['name'];final q=TextEditingController(text:'1'),days=TextEditingController(text:'1'),rate=TextEditingController(text:'${data.items.first['rate']}');final ok=await showDialog<bool>(context:c,builder:(_)=>StatefulBuilder(builder:(c,set)=>AlertDialog(title:const Text('New Rental'),content:SingleChildScrollView(child:Column(children:[DropdownButtonFormField(value:customer,items:data.customers.map((x)=>DropdownMenuItem(value:x['name'] as String,child:Text(x['name']))).toList(),onChanged:(v)=>set(()=>customer=v!),decoration:const InputDecoration(labelText:'Customer')),DropdownButtonFormField(value:item,items:data.items.map((x)=>DropdownMenuItem(value:x['name'] as String,child:Text(x['name']))).toList(),onChanged:(v){set((){item=v!;rate.text='${data.items.firstWhere((x)=>x['name']==item)['rate']}';});},decoration:const InputDecoration(labelText:'Item')),_field(q,'Quantity',number:true),_field(days,'Days',number:true),_field(rate,'Rate (manual edit allowed)',number:true)])),actions:[TextButton(onPressed:()=>Navigator.pop(c,false),child:const Text('Cancel')),FilledButton(onPressed:()=>Navigator.pop(c,true),child:const Text('Create'))])));if(ok==true){final it=data.items.firstWhere((x)=>x['name']==item);final qty=int.tryParse(q.text)??0;if(qty>(it['available']??0)){ScaffoldMessenger.of(c).showSnackBar(const SnackBar(content:Text('Not enough available quantity.')));return;}final amt=qty*(double.tryParse(rate.text)??0)*(int.tryParse(days.text)??1);it['available']=(it['available'] as int)-qty;final r={'id':data.id(),'date':_date(),'customer':customer,'item':item,'qty':qty,'days':int.tryParse(days.text)??1,'rate':double.tryParse(rate.text)??0,'amount':amt,'status':'issued'};data.rentals.add(r);data.invoices.add({...r,'invoice':'INV-${data.invoices.length+1}'});await data.save();onChanged();}}
  Future<void> _receive(BuildContext c)async{final active=data.rentals.where((x)=>x['status']=='issued').toList();if(active.isEmpty){ScaffoldMessenger.of(c).showSnackBar(const SnackBar(content:Text('No issued items found.')));return;}String id=active.first['id'];final q=TextEditingController(text:'${active.first['qty']}');final ok=await showDialog<bool>(context:c,builder:(_)=>StatefulBuilder(builder:(c,set)=>AlertDialog(title:const Text('Receive Item'),content:Column(mainAxisSize:MainAxisSize.min,children:[DropdownButtonFormField(value:id,items:active.map((x)=>DropdownMenuItem(value:x['id'] as String,child:Text('${x['customer']} • ${x['item']}'))).toList(),onChanged:(v)=>set(()=>id=v!),decoration:const InputDecoration(labelText:'Rental')), _field(q,'Received Quantity',number:true)]),actions:[TextButton(onPressed:()=>Navigator.pop(c,false),child:const Text('Cancel')),FilledButton(onPressed:()=>Navigator.pop(c,true),child:const Text('Receive'))])));if(ok==true){final r=data.rentals.firstWhere((x)=>x['id']==id);final got=int.tryParse(q.text)??0;final it=data.items.firstWhere((x)=>x['name']==r['item']);it['available']=(it['available'] as int)+got;if(got>=(r['qty'] as int)){r['status']='received';}else{r['qty']=(r['qty'] as int)-got;}await data.save();onChanged();}}
