Widget _field(TextEditingController x,String label,{bool number=false})=>Padding(padding:const EdgeInsets.only(bottom:10),child:TextField(controller:x,keyboardType:number?TextInputType.number:null,decoration:InputDecoration(labelText:label,border:const OutlineInputBorder())));
String _date()=>DateTime.now().toString().split(' ').first.split('-').reversed.join('/');

class ItemsPage extends StatelessWidget {final Store data;final VoidCallback onChanged;const ItemsPage({super.key,required this.data,required this.onChanged});@override Widget build(BuildContext c)=>SafeArea(child:ListView(padding:const EdgeInsets.all(18),children:[Row(children:[const Expanded(child:Text('Items',style:TextStyle(fontSize:28,fontWeight:FontWeight.w800))),FilledButton.icon(onPressed:()=>Home(data:data,onChanged:onChanged)._addItem(c),icon:const Icon(Icons.add),label:const Text('Add'))]),const SizedBox(height:12),...data.items.map((i)=>Card(child:ListTile(leading:CircleAvatar(backgroundColor:mint,child:const Icon(Icons.inventory_2,color:teal)),title:Text(i['name'],style:const TextStyle(fontWeight:FontWeight.w700)),subtitle:Text('${i['category']} • ${i['type']} • ₹${i['rate']}'),trailing:Text('${i['available']}/${i['qty']}',style:const TextStyle(fontWeight:FontWeight.w800))))),if(data.items.isEmpty)const Padding(padding:EdgeInsets.all(40),child:Center(child:Text('No items added')))]));}

